import { IMG } from './theme.js';

// Resolve a product image filename → built URL. Vite's import.meta.glob hashes
// each file at build time and tree-shakes anything not referenced below.
const productImages = import.meta.glob(
  '../assets/products/*.{webp,jpg,jpeg,png,avif}',
  { eager: true, query: '?url', import: 'default' }
);
const getImg = (filename) => productImages[`../assets/products/${filename}`] || null;

